// Strip a fetched HTML page down to readable text and cap length for the LLM.
const raw = $input.first().json.data || $input.first().json.body || '';
let text = String(raw);

// Drop script/style/noscript blocks, then all tags, then decode a few entities.
text = text
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '\"')
  .replace(/&#39;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/\s+/g, ' ')
  .trim();

// Cap at ~24000 chars (~6k tokens) so we stay well inside the model context.
const MAX = 24000;
if (text.length > MAX) text = text.slice(0, MAX);

const tone = $('Paste Content URL').first().json['Tone'] || 'professional';
const sourceUrl = $('Paste Content URL').first().json['Content URL'] || '';

return [{ json: { sourceUrl, tone, articleText: text, charCount: text.length } }];

// Split Claude's delimited response into the three pieces.
const out = $input.first().json;
const text = (out.content && out.content[0] && out.content[0].text) ? out.content[0].text : '';

function section(name, body) {
  const marker = '===' + name + '===';
  const start = body.indexOf(marker);
  if (start === -1) return '';
  const rest = body.slice(start + marker.length);
  const next = rest.match(/===[A-Z]+===/);
  const end = next ? next.index : rest.length;
  return rest.slice(0, end).trim();
}

const twitter = section('TWITTER', text);
const linkedin = section('LINKEDIN', text);
const newsletter = section('NEWSLETTER', text);

return [{ json: {
  sourceUrl: $('Extract Article Text').first().json.sourceUrl,
  tone: $('Extract Article Text').first().json.tone,
  twitterThread: twitter,
  linkedinPosts: linkedin,
  newsletterBlurb: newsletter,
  raw: text
} }];
